/* eslint-disable no-console */
import EventEmitter from 'eventemitter3';
import { IOrientationState, OrientationEvents, OrientationStateBuilder, OrientationValue } from './orientation';
import { DeviceInfo } from './device-info';
import { VirtualKeyboard } from './virtual-keyboard';
import { PageVisibility } from './visibility';
import { DeviceType } from './device-info/device-type';
import { debounce } from '@game-studio/utilities';
import { DeviceOptions } from './types';

// TODO: investigate whether this delay can be shorter, once the consolidated shell is ready.
// 250 was too quick on iPad Pro (0872)
const ORIENTATION_DEBOUNCE_MS = 500;
const VISIBILITY_INTERVAL_MS = 150;
const NO_END_TIMEOUT_MS = 1750;

export class DeviceOrientation extends EventEmitter<OrientationEvents> implements IOrientationState {
    private mState: IOrientationState;
    public get isChanging(): boolean {
        return this.state.isChanging;
    }
    private set state(value: IOrientationState) {
        this.mState = value;
    }
    public get state(): IOrientationState {
        return this.mState;
    }

    public get value(): OrientationValue {
        return this.state.value;
    }

    private lastOrientation: IOrientationState;

    private catchupTimeoutId?: number;
    private catchupIntervalId?: number;
    private builder: OrientationStateBuilder;
    private isFirstOrientation: boolean = true;

    constructor(private deviceType: DeviceType, private deviceInfo: DeviceInfo, private keyboard: VirtualKeyboard, pageVisibility: PageVisibility, options: Partial<DeviceOptions>) {
        super();
        this.builder = new OrientationStateBuilder(deviceType, deviceInfo, options.ignoreInversion, options.forceOrientation);
        this.state = this.builder.build();

        this.lastOrientation = { ...this.state };

        window.addEventListener('internal:orientationchange', () => {
            this.emitState(this.builder.build(true));
        });

        pageVisibility.addListener('visibilityChanged', this.onVisibilityChange.bind(this));
        // this.setupScreenOrientationListener();

        if (this.deviceType.isDesktop) {
            this.desktopResize();
        } else {
            this.createMobileResize(options.widthBasedOrientation ?? false, () => {
                window.dispatchEvent(new Event('internal:orientationchange'));
            });
            this.createMobileResize(true, () => {
                keyboard.isOpen = false;
            });
        }
    }

    // This is causing multiple events as the "other checkers" are still running as well.
    /**
     * setup listener for screen orientation change event. 
     * (will work for 92.5% of orientation change cases, our other checkers will handle it for every other use case)
     * https://caniuse.com/mdn-api_screenorientation_change_event
     */
    // private setupScreenOrientationListener() {
    //     if (window.screen && window.screen.orientation && window.screen.orientation.addEventListener) {
    //         window.screen.orientation.addEventListener('change', () => {
    //             this.emitState(this.builder.build(true));
    //         });
    //     }
    // }

    private emitState(state: IOrientationState) {
        // Used to call an orientation change once on load for desktop
        const emitFirstOrientation = this.isFirstOrientation && this.deviceType.isDesktop;
        const isChanging = state.isChanging || state.isChanging !== this.state.isChanging;
        if (this.state.value !== state.value || isChanging || emitFirstOrientation) {
            this.state = state;
            this.isFirstOrientation = false;
            this.emit('onOrientationStateChanged', { ...this.state });
        } else {
            this.emit('onResize');
        }
    }

    private createMobileResize(widthBasedOrientation: boolean, methodToCall: () => void): void {
        let windowWidth = window.innerWidth || 1;
        let lastWidth = window.innerWidth || 1;

        const debouncedResize = debounce(() => {
            if (widthBasedOrientation && windowWidth === lastWidth) return;
            lastWidth = windowWidth;
            methodToCall();
        }, ORIENTATION_DEBOUNCE_MS);

        window.addEventListener('resize', (event) => {
            const target = event.target as Window;
            windowWidth = target.innerWidth || 1;
            debouncedResize();
        });
    }

    private desktopResize(): void {
        window.addEventListener('resize', () => {
            window.dispatchEvent(new Event('internal:orientationchange'));
        });
    }

    get isLandscape() {
        return this.state.isLandscape;
    }

    get isPortrait() {
        return this.state.isPortrait;
    }

    get isInverted() {
        return this.builder.isInverted;
    }

    private onVisibilityChange(isVisible: boolean) {
        window.clearTimeout(this.catchupTimeoutId);
        window.clearInterval(this.catchupIntervalId);
        const stateNotChanging = this.builder.build();
        if (!isVisible) {
            this.lastOrientation = stateNotChanging;
        } else if (isVisible && this.lastOrientation.value !== stateNotChanging.value) {
            let intervalCount = 0;
            this.catchupIntervalId = window.setInterval(() => {
                this.emitState(this.builder.build(intervalCount === 0));
                ++intervalCount;
            }, VISIBILITY_INTERVAL_MS);
            this.catchupTimeoutId = window.setTimeout(() => {
                window.clearInterval(this.catchupIntervalId);
            }, NO_END_TIMEOUT_MS);
        }
    }
}
